"""Polish the smaller cards view on the Tables page (Karim 2026-11-22).
Whole-card blur in the topic colour, LIVE as plain green text (no minutes, no box),
topic under LIVE, no coloured rings on avatars, seats free + button on one line.
Idempotent: re-run after rebuilding help/live-pages/agenda.html."""
import re,sys
P=sys.argv[1] if len(sys.argv)>1 else "help/live-pages/agenda.html"
CSS='main.land .live .tbl .tb{min-width:0!important}\n@media (min-width:1101px),(min-width:641px) and (max-width:900px){main.land .live .ttop{width:136px!important}main.land .live .ttop .ring{width:122px!important;height:122px!important}main.land .live .ttop .board{inset:26px!important}main.land .live .ttop .seat{width:23px!important;height:23px!important;margin:-11.5px 0 0 -11.5px!important}}\nmain.land .live .tbl .tf .jbtn{padding-inline:12px!important}\nmain.land .live .tbl .tf{gap:8px!important}\nmain.land .live .tbl .tf .jbtn{flex:none;margin-left:auto}\n/* whole-card blurry background */\nmain.land .live .tbl{position:relative;isolation:isolate;overflow:hidden}\nmain.land .live .tbl>.tbg{position:absolute;z-index:-2}\nmain.land .live .tbl>.tbg.gen{inset:-60px;filter:blur(40px) saturate(1.05)}\nmain.land .live .tbl>.tbg:not(.gen){inset:-30px;background-position:center;background-size:cover;filter:blur(22px) brightness(.55) saturate(1.1)}\nmain.land .live .tbl::after{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;\n  background:rgba(27,33,68,.42)}\nmain.land .live .ttop{background:transparent!important}\n/* live: a status, not a button */\nmain.land .live .tbl .lpill{background:none!important;padding:0!important;height:auto!important;border:0!important;box-shadow:none!important;color:#3DDC84!important;font-weight:600;letter-spacing:.08em;gap:8px;white-space:nowrap}\nmain.land .live .tbl .lpill i{width:8px!important;height:8px!important;background:#3DDC84!important;box-shadow:none!important;border-radius:50%;width:7px!important;height:7px!important}\nmain.land .live .trow{flex-direction:column!important;align-items:flex-start!important;gap:6px!important}\nmain.land .live .topic{white-space:nowrap}\n/* footer: seats + button on one line, pinned to the bottom */\nmain.land .live .tb{justify-content:flex-start!important}\nmain.land .live .tf{display:flex!important;flex-direction:row!important;align-items:center!important;justify-content:space-between!important;flex-wrap:nowrap!important;margin-top:auto!important;padding-top:10px}\nmain.land .live .tf .left{white-space:nowrap}\n/* seats: lighter, finer */\nmain.land .live .ttop .seat{border:1.5px solid rgba(27,33,68,.85)!important}\nmain.land .live .ttop .seat.host,main.land .live .ttop .seat.talk{box-shadow:none!important}\nmain.land .live .ttop .seat.open{border:1.2px dashed rgba(238,241,255,.38)!important;background:rgba(255,255,255,.04)!important}\nmain.land .live .ttop .board{box-shadow:inset 0 0 0 2px color-mix(in srgb,var(--c) 70%,#fff 10%),0 6px 20px rgba(5,8,25,.35)!important}\nmain.land .live .ttop .board.photo{outline:2px solid color-mix(in srgb,var(--c) 70%,#fff 10%);outline-offset:-2px}\n/* phone: same blurry wash on the card */\n@media (max-width:640px){main.land .live .tbl>.tbg{display:block!important}main.land .live .tbl::after{background:rgba(27,33,68,.6)}}\nmain.land .live .tbl .tb{padding-right:16px!important}\nmain.land .live .tbl .meta{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\nmain.land .live .tbl .lpill{font-size:14px!important;font-weight:700!important;letter-spacing:.1em!important}\n'
JS='(function(){\nfunction c4(a){var m=(a.getAttribute("style")||"").match(/--c:\\s*(#[0-9A-Fa-f]{6})/);return m?m[1]:"#A9B0D6"}\nfunction polish(){document.querySelectorAll("main.land .live .tbl:not([data-cp])").forEach(function(a){\n a.setAttribute("data-cp","1");var t=a.querySelector(".ttop>.tbg");if(!t)return;a.insertBefore(t,a.firstChild);var c=c4(a);\n t.className="tbg gen";t.setAttribute("style","background:radial-gradient(60% 100% at 20% 35%,"+c+"88,transparent 75%),radial-gradient(70% 110% at 70% 55%,"+c+"33,transparent 80%),radial-gradient(60% 90% at 92% 85%,#7C5CFF55,transparent 75%),radial-gradient(45% 60% at 75% 5%,#17C3C833,transparent 75%),linear-gradient(100deg,color-mix(in srgb,"+c+" 12%,#252B52),#252B52)");\n var l=a.querySelector(".lpill");if(l)l.textContent="Live";});}\nvar busy=false;new MutationObserver(function(){if(busy)return;busy=true;requestAnimationFrame(function(){polish();busy=false})}).observe(document.documentElement,{childList:true,subtree:true,attributes:true,attributeFilter:["class"]});\nif(document.readyState!=="loading")polish();else document.addEventListener("DOMContentLoaded",polish);\n})();'
s=open(P,encoding="utf-8").read()
s=re.sub(r'<style id="card-polish">.*?</style>','',s,flags=re.S)
s=re.sub(r'<script id="card-polish-js">.*?</script>','',s,flags=re.S)
block='<style id="card-polish">'+CSS+'</style><script id="card-polish-js">'+JS+'</script>'
i=s.rfind("</body>")
s=s[:i]+block+s[i:] if i>=0 else s+block
open(P,"w",encoding="utf-8").write(s)
print("patched",P)
